-- GENERATED by scripts/seed/generate.mjs. Rough default prices (INR per kg or litre, as purchased).
-- Prices vary by city, season and shop: add rows for your own region or edit these.
insert into public.food_price_estimates (food_database_id, region, price_per_kg_or_litre, currency, source)
select f.id, 'default', v.price, 'INR', 'NutriTrack default rough estimate (prices vary by city, season and shop; edit for your region)'
from (values
('roti chapati', 40),
('roti with ghee', 40),
('plain paratha', 40),
('bajra roti', 45),
('ragi roti', 60),
('white bread slice', 125),
('brown bread slice', 140),
('cooked white rice', 55),
('cooked brown rice', 90),
('poha', 60),
('rolled oats cooked in water', 180),
('besan chilla', 90),
('toor dal cooked', 165),
('dal tadka', 165),
('moong dal cooked', 125),
('masoor dal cooked', 95),
('chana dal cooked', 100),
('rajma curry', 150),
('chole', 130),
('boiled chickpeas black chana', 95),
('moong sprouts', 100),
('soya chunks', 130),
('boiled egg', 140),
('toned milk', 56),
('curd dahi', 80),
('buttermilk', 80),
('paneer', 380),
('ghee', 650),
('butter', 550),
('cooking oil', 140),
('chicken breast cooked', 240),
('chicken curry', 240),
('tandoori chicken', 240),
('fish curry', 260),
('fried fish', 260),
('mixed vegetable sabzi', 50),
('aloo sabzi', 30),
('aloo gobi', 40),
('palak sabzi', 40),
('bhindi sabzi', 60),
('baingan bharta', 45),
('green salad', 40),
('cucumber', 30),
('tomato', 40),
('onion', 35),
('carrot', 45),
('boiled potato', 30),
('boiled sweet potato', 50),
('banana', 60),
('apple', 180),
('orange mosambi', 100),
('guava', 70),
('papaya', 50),
('mango', 100),
('watermelon', 25),
('peanuts', 130),
('almonds', 800),
('roasted chana', 120),
('makhana', 1200),
('peanut butter', 300),
('sugar', 48)
) as v(normalized_name, price)
join public.food_database f on f.normalized_name = v.normalized_name
on conflict (food_database_id, region) do update
  set price_per_kg_or_litre = excluded.price_per_kg_or_litre, source = excluded.source, observed_at = now();
